window.renderPoetryCase=(t,href)=>{
 const image=(key,z,e,extra='')=>`<figure class="poetry-image ${extra}"><img src="assets/poetry/${key}.jpg" alt="${t(z,e)}" ${key==='hero'?'fetchpriority="high"':'loading="lazy"'}></figure>`;
 const copy=(z,e,p,q)=>`<section class="poetry-copy">${z==='主视觉设计思路'?'':`<h2>${t(z,e)}</h2>`}<p>${t(p,q)}</p></section>`;
 return `<article class="poetry-case">${image('hero','顾客在超市橱窗前阅读儿童诗歌','Customers reading children’s poetry at a supermarket window','poetry-hero')}<section class="poetry-project-intro"><div class="poetry-project-intro-copy"><p>${t('2022年六一儿童节，大润发将来自凉山彝族自治州普格县大槽乡中心校孩子们的诗歌带进超市，在成都、济南、沈阳、杭州、武汉五座城市的门店举办儿童诗歌展，并联动线上新媒体平台传播。孩子们以诗句记录自己与日常生活，也描绘对长大后的想象，让原本写在纸上的愿望走进公众的生活现场。','For Children’s Day in 2022, RT-MART brought poems by children from the central school of Dacao Township, Puge County, Liangshan Yi Autonomous Prefecture, into stores in Chengdu, Jinan, Shenyang, Hangzhou and Wuhan, supported by online communication. Their poems describe everyday life and imagined futures, bringing wishes written on paper into public view.')}</p><p>${t('本项目围绕诗歌展的主题视觉与空间传播展开，以田字格和稚嫩的手写字体构建视觉语言，将诗句延展至鱼缸、货架、地面与店外橱窗。通过诗歌与商品、动线及空间的呼应，让日常购物场景成为阅读与交流的载体，也让孩子们的表达被更多人看见。','The project develops the exhibition’s visual identity and spatial communication through writing grids and childlike handwriting. Poems extend across fish tanks, shelves, floors and storefront windows, connecting with products and circulation to turn everyday shopping into an opportunity for reading and exchange.')}</p></div><div class="poetry-project-intro-meta"><span>${t('项目 / 品牌：大润发','Project / Brand: RT-MART')}</span><span>${t('年份：2022','Year: 2022')}</span><span>${t('服务：主题视觉 / 空间图文 / 传播延展','Services: Key visual / Spatial graphics / Campaign applications')}</span></div></section>${copy('主视觉设计思路','Visual direction','从共同的书写记忆出发，以横竖排布的田字格还原作文本的形态，用稚嫩的手写字体回应孩子们的诗句。熟悉的格子与童真的文字，让日常空间拥有了不同的阅读方式。','The visual language draws on a shared memory of learning to write. Horizontal and vertical grids evoke exercise books, while childlike handwriting carries the poems. Familiar structures and a youthful voice invite a different kind of reading in everyday spaces.')}<section class="poetry-mindmap" aria-label="${t('主视觉设计思路图','Visual concept diagram')}"><svg viewBox="0 0 900 300" aria-hidden="true"><path d="M380 150L570 75M380 150L570 225"/></svg><div class="poetry-root">${t('大众共同记忆的<br><strong>符号</strong>','A shared memory<br><strong>of writing</strong>')}</div><div class="poetry-node poetry-node-top">${t('田字格作文本','Writing grids')}</div><div class="poetry-node poetry-node-bottom">${t('稚嫩手写体','Childlike handwriting')}</div></section>${image('poem','红底白字的田字格儿童诗歌主视觉','Children’s poetry in white writing grids on red')}${copy('为每个场景找到一首诗','A poem for each place','先记录门店不同区域与载体，从墙面、地面到鱼缸与货架，再根据场景选择合适的诗歌进行视觉延展。让诗句与眼前的商品、动线和空间产生关联。','The design began with the store itself: walls, floors, fish tanks and shelving. Poems were then selected and adapted to each setting, connecting their words with products, circulation and the surrounding space.')}${image('locations','不同门店区域与展示载体的调研拼图','A study of store locations and display surfaces')}${image('design','诗歌结合商品与空间的图文设计延展','Poems adapted to products and spatial settings')}${image('fish','鱼缸前的儿童诗歌展示','Children’s poetry displayed on a fish tank')}${image('market','购物场景中的诗歌展','Poetry among everyday shoppers')}${image('fruit','水果陈列中的诗歌视觉','Poetry alongside fruit displays')}${image('vegetables','蔬菜与水果区域的诗歌应用','Poetry in the produce aisles')}${image('spaces','店外、地面与回收箱上的诗歌','Poetry outside the store, on floors and recycling points')}${image('window','夜色中的超市诗歌橱窗','The poetry window after dark')}<section class="poetry-results"><div><h2>${t('传播反馈','Campaign response')}</h2><p>${t('据原项目资料，六一当天人民日报发起相关话题，记录孩子们的诗歌在超市被看见的瞬间；线上讨论与门店展览相互呼应，让诗句从购物现场走向更广泛的公众。','According to the original project recap, People’s Daily shared the campaign on Children’s Day. Online discussion extended the reach of the in-store exhibition, bringing the poems to a wider audience.')}</p><dl><div><dt>${t('微博热搜','Weibo trending rank')}</dt><dd>31</dd></div><div><dt>${t('话题阅读超','Reported topic views')}</dt><dd>${t('2500万','25M+')}</dd></div></dl><small>${t('数据依据原项目资料展示。','Figures reproduced from the original project recap.')}</small></div>${image('response','原项目传播反馈的微博页面记录','Weibo coverage from the original project recap')}</section></article><section class="next-project"><a href="${href('work')}">↖ ${t('返回全部案例','Back to all projects')}</a><a href="${href('project','&id=metro')}"><span>${t('下一个项目','Next project')}</span><strong>${t('闲鱼文学奖 · 地铁车厢视觉','Xianyu Literature Awards · Metro Exhibition')} ↗</strong></a></section>`;
};
